// Hand-written. Not generated by Speakeasy.
package customtypes

import (
	"context"
	"strings"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/diag"
	"github.com/hashicorp/terraform-plugin-framework/path"
)

func validatePublicJWKS(t *testing.T, doc string) diag.Diagnostics {
	t.Helper()
	return ValidateDocument(path.Root("jwks"), doc, true)
}

// Authlete strips these without reporting an error, so the configuration and
// the server disagree for ever. Measured: an RSA private key sent to a client
// comes back as kty, n, e, kid, alg, use.
func TestClientRefusesAPrivateKey(t *testing.T) {
	for _, member := range []string{"d", "p", "q", "dp", "dq", "qi"} {
		t.Run(member, func(t *testing.T) {
			doc := `{"keys":[{"kty":"RSA","kid":"k","alg":"RS256","use":"sig","n":"AQAB","e":"AQAB","` +
				member + `":"c2VjcmV0"}]}`
			d := validatePublicJWKS(t, doc)
			if !d.HasError() {
				t.Fatalf("accepted a key carrying %q", member)
			}
			if !strings.Contains(d.Errors()[0].Detail(), member) {
				t.Errorf("error does not name the member: %s", d.Errors()[0].Detail())
			}
		})
	}
}

// "oth" carries the additional primes of a multi-prime RSA private key. It is
// an array of objects, not a string, so the loop over privateMembers steps
// straight past it and the key reads as public. Found in review: a key set
// written by hand with oth passed validation and the primes reached state.
//
// RFC 7518 requires d, p, q, dp, dq and qi alongside oth, so a well-formed
// key is caught by those anyway. A hand-written one need not be well formed,
// and the private material is there regardless.
func TestClientRefusesOtherPrimes(t *testing.T) {
	for name, doc := range map[string]string{
		"oth alone": `{"keys":[{"kty":"RSA","kid":"k","n":"AQAB","e":"AQAB",` +
			`"oth":[{"r":"cHJpbWU","d":"ZXhwb25lbnQ","t":"Y29lZmY"}]}]}`,
		"oth alongside the members it is supposed to accompany": `{"keys":[{"kty":"RSA","kid":"k","n":"AQAB","e":"AQAB",` +
			`"d":"ZA","p":"cA","q":"cQ","dp":"ZHA","dq":"ZHE","qi":"cWk",` +
			`"oth":[{"r":"cHJpbWU","d":"ZXhwb25lbnQ","t":"Y29lZmY"}]}]}`,
	} {
		t.Run(name, func(t *testing.T) {
			d := validatePublicJWKS(t, doc)
			if !d.HasError() {
				t.Fatal("accepted a key carrying other-primes data, so the private " +
					"primes reach Terraform state for a key Authlete never kept")
			}
		})
	}
}

// An empty or absent oth must not be refused. A public key that happens to
// carry "oth":[] holds no private material.
func TestClientAcceptsAnEmptyOtherPrimes(t *testing.T) {
	d := validatePublicJWKS(t,
		`{"keys":[{"kty":"RSA","kid":"k","alg":"RS256","use":"sig","n":"AQAB","e":"AQAB","oth":[]}]}`)
	if d.HasError() {
		t.Errorf("refused a public key with an empty oth: %v", d.Errors())
	}
}

// Measured: a symmetric key sent to a client is stored as {"keys":[]}.
func TestClientRefusesASymmetricKey(t *testing.T) {
	d := validatePublicJWKS(t,
		`{"keys":[{"kty":"oct","kid":"k","alg":"HS256","use":"sig","k":"MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY"}]}`)
	if !d.HasError() {
		t.Fatal("accepted a symmetric key, which Authlete discards without saying so")
	}
	var found bool
	for _, e := range d.Errors() {
		if strings.Contains(e.Summary(), "Symmetric key in a client") {
			found = true
		}
	}
	if !found {
		t.Errorf("no error about the key being symmetric: %v", d.Errors())
	}
}

func TestClientAcceptsPublicKeys(t *testing.T) {
	for name, doc := range map[string]string{
		"RSA":     `{"keys":[{"kty":"RSA","kid":"k","alg":"RS256","use":"sig","n":"AQAB","e":"AQAB"}]}`,
		"EC":      `{"keys":[{"kty":"EC","kid":"k","crv":"P-256","alg":"ES256","use":"sig","x":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","y":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"}]}`,
		"Ed25519": `{"keys":[{"kty":"OKP","kid":"k","crv":"Ed25519","alg":"EdDSA","use":"sig","x":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"}]}`,
		// An empty private member is what the server itself returns for some
		// documents; it carries no key material, so it is not an error.
		"an empty d member": `{"keys":[{"kty":"RSA","kid":"k","alg":"RS256","use":"sig","n":"AQAB","e":"AQAB","d":""}]}`,
	} {
		t.Run(name, func(t *testing.T) {
			if d := validatePublicJWKS(t, doc); d.HasError() {
				t.Errorf("refused a public key: %v", d.Errors())
			}
		})
	}
}

// The checks a service already had still apply to a client.
func TestClientInheritsTheSharedChecks(t *testing.T) {
	for name, doc := range map[string]string{
		"duplicate kid":  `{"keys":[{"kty":"RSA","kid":"d","alg":"RS256","use":"sig","n":"AQAB","e":"AQAB"},{"kty":"EC","kid":"d","crv":"P-256","alg":"ES256","use":"sig"}]}`,
		"missing kid":    `{"keys":[{"kty":"RSA","alg":"RS256","use":"sig","n":"AQAB","e":"AQAB"}]}`,
		"HMAC on RSA":    `{"keys":[{"kty":"RSA","kid":"k","alg":"HS256","use":"sig","n":"AQAB","e":"AQAB"}]}`,
		"wrong EC curve": `{"keys":[{"kty":"EC","kid":"k","crv":"P-384","alg":"ES256","use":"sig"}]}`,
		"unknown use":    `{"keys":[{"kty":"RSA","kid":"k","alg":"RS256","use":"bogus","n":"AQAB","e":"AQAB"}]}`,
	} {
		t.Run(name, func(t *testing.T) {
			if d := validatePublicJWKS(t, doc); !d.HasError() {
				t.Errorf("accepted %s: %s", name, doc)
			}
		})
	}
}

// Semantic equality has to survive the wrapping, or a client's JWK Set goes
// back to diffing on whitespace.
func TestPublicJWKSStillComparesByMeaning(t *testing.T) {
	a := NewPublicJWKSValue("{\n  \"keys\": [\n    {\n      \"kty\": \"RSA\",\n      \"kid\": \"k1\"\n    }\n  ]\n}")
	b := NewPublicJWKSValue(`{"keys":[{"kid":"k1","kty":"RSA"}]}`)

	equal, diags := a.StringSemanticEquals(context.Background(), b)
	if diags.HasError() {
		t.Fatalf("unexpected diagnostics: %v", diags)
	}
	if !equal {
		t.Error("two JWK Sets differing only in formatting compared unequal")
	}
}
